def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    arity = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(s):
        if not s or any(c < "0" or c > "9" for c in s):
            return None

        # Small chunks avoid Python's limit on decimal string conversion.
        value = 0
        for start in range(0, len(s), 9):
            chunk = s[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if arity.get(verb) != len(parts) or not all(parts):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, old_balance, old_frozen in history.pop():
                if old_balance is None:
                    balances.pop(name, None)
                else:
                    balances[name] = old_balance

                if old_frozen:
                    frozen.add(name)
                else:
                    frozen.discard(name)
            continue

        amount = None
        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        account = parts[1]
        affected = (account,)

        if verb == "open":
            valid = account not in balances
        elif account not in balances:
            valid = False
        elif verb == "deposit":
            valid = True
        elif verb == "withdraw":
            valid = account not in frozen and balances[account] >= amount
        elif verb == "transfer":
            target = parts[2]
            valid = (
                account != target
                and target in balances
                and account not in frozen
                and balances[account] >= amount
            )
            affected = (account, target)
        elif verb == "freeze":
            valid = account not in frozen
        else:  # unfreeze
            valid = account in frozen

        if not valid:
            rejected.append(index)
            continue

        history.append([
            (name, balances.get(name), name in frozen)
            for name in affected
        ])

        if verb == "open":
            balances[account] = amount
        elif verb == "deposit":
            balances[account] += amount
        elif verb == "withdraw":
            balances[account] -= amount
        elif verb == "transfer":
            balances[account] -= amount
            balances[target] += amount
        elif verb == "freeze":
            frozen.add(account)
        else:
            frozen.remove(account)

    return balances, rejected
